from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..util import wrap_result
from ..validators import IsString, IsOneOf
from ..converter import to_bool


class AutoConnectionInterface(BaseInterface):

    def register_autoconnection(self, site_id, timeout=120, alias="default"):
        """Register autoconnection.

        :param string site_id: Site ID.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(site_id)

        self.store.get(alias).execute_procedure("registerAutoconnection", {"siteId": site_id}, timeout)

    def update_trs_autoconnection_params(self, timeout=120, alias="default", **parameters):
        """Update TRS autoconnection params.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :Available parameters:
            * **eNBIpAddress** (string)
            * **netPrefixLength** (integer)
            * **defaultGateway** (string)
            * **vlanId** (integer)
            * **identificationServerIpAddress** (string)
            * **vnpGatewayIpAddress** (string)
            * **cmpServerIpAddress** (string)
            * **cmpServerPort** (integer)
            * **cmpSubjectName** (string)
            * **cmpDirectory** (string)
        """
        timeout = timestr_to_secs(timeout)

        self.store.get(alias).execute_procedure("updateTrsAutoconnectionParams", parameters, timeout)

    def get_autoconnection_status(self, timeout=10, alias="default"):
        """Get autoconnection status.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: autoConnectionStatus parameter of AUTOCONFIG object
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("getAutoconnectionStatus", {}, timeout)

    @wrap_result
    def get_trs_autoconnection_status(self, timeout=10, alias="default"):
        """Get TRS autoconnection status.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: object
        :return: FTM object with parameters: ipStatus, dhcpStatus, certificateStatus
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("getTrsAutoconnectionStatus", {}, timeout)

    def autoconnection_clear_and_restart(self, remove_site_id="False", remove_security_credentials="False", timeout=60, alias="default"):
        """ Clears autoconnection and perform restart

        :param bool remove_site_id:  True is site Id should be removed
        :param bool remove_security_credentials:  True if security credentials should be removed.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        remove_site_id = to_bool(remove_site_id)
        remove_security_credentials = to_bool(remove_security_credentials)
        parameters = {"removeSiteId": remove_site_id, "removeSecurityCredentials": remove_security_credentials}
        self.store.get(alias).execute_procedure("autoconnClearAndRestart", parameters, timeout)

    def autoconfiguration_report(self, timeout=30, alias="default"):
        """ Returns autoconfiguration report

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: dict
        :return: Autoconfiguration report
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_procedure("autoconfReport", {}, timeout)

    def change_autoconfiguration_status(self, state, timeout=30, alias="default"):
        """
        Change autoconfiguration status

        :param string state: autoconfigurationState <Disable | Enable>
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        state = state.title()
        IsOneOf("Disable", "Enable").check(state)
        self.store.get(alias).execute_procedure("changeAutoconfigurationStatus", {"autoconfigurationState": state}, timeout)

    def set_autoconnection_transport_params(self, timeout=120, alias="default", **parameters):
        """Set autoconnection transport params.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :Available parameters:
            * **mPlaneIpAddress** (string)
            * **mPlaneIpPrefix** (integer)
            * **defaultGateway** (string)
            * **vlanId** (integer)
            * **identificationServerIpAddress** (string)
            * **ipSecIpAddress** (string)
            * **cmpServerIpAddress** (string)
            * **cmpServerPort** (integer)
            * **cmpDirectory** (string)
            * **caSubjectName** (string)
        """
        timeout = timestr_to_secs(timeout)

        self.store.get(alias).execute_procedure("setAutoConnectionTransportParams", parameters, timeout)

    def get_pnp_report(self, output_file_name, timeout=60, alias="default"):
        """
        Saves pnp report under given output file name.

        :param string output_file_name: Path to save report.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure("getPnpReport", {}, timeout, output_file_name=output_file_name)

    def set_autoconnection_site_id(self, site_id, timeout=60, alias="default"):
        """
        Set autoconnection side id

        :param string site_id: site id to be set
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(site_id)
        timeout = timestr_to_secs(timeout)

        self.store.get(alias).execute_procedure("autoconnectionSiteID", {"siteId": site_id}, timeout)
